  </style>
</head>
<body>
  <div class="container">
    <h1>Hello, {{firstName}} {{lastName}}! 👋</h1>
    <p>Welcome to your <span class="highlight">{{plan}}</span> plan.</p>
    <p>We're excited to have you at <strong>{{company}}</strong> as our {{role}}.</p>
    <p>Your registered email is: {{email}}</p>
    <p>Location: {{location}}</p>
    <div class="footer">
      <p>This email was sent to {{email}}. If you have any questions, contact support.</p>
    </div>
  </div>
</body>
</html>`;

            // --- Default user profile ---
            const DEFAULT_PROFILE = {
                firstName: 'John',
                lastName: 'Doe',
                email: 'john.doe@example.com',
                company: 'Acme Corporation',
                role: 'Senior Software Engineer',
                location: 'San Francisco, CA',
                plan: 'Pro'
            };

            // --- Current state ---
            let currentProfile = { ...DEFAULT_PROFILE };
            let currentTemplate = DEFAULT_TEMPLATE;
            let generatedHtml = '';

            // --- Helper: Escape HTML for safe display in code output ---
            function escapeHtml(str) {
                const div = document.createElement('div');
                div.textContent = str;
                return div.innerHTML;
            }

            // --- Helper: Syntax highlight for HTML code output ---
            function highlightHtml(html) {
                // Escape first
                let escaped = escapeHtml(html);

                // Highlight tags
                escaped = escaped.replace(
                    /(&lt;\/?)([a-zA-Z][a-zA-Z0-9-]*)((?:\s+[^&]*?)?)(\/?&gt;)/g,
                    function(match, openBracket, tagName, attrs, closeBracket) {
