            function validateInputs(profile) {
                const errors = [];
                if (!profile.firstName) errors.push('First name is required.');
                if (!profile.lastName) errors.push('Last name is required.');
                if (!profile.email) {
                    errors.push('Email is required.');
                } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(profile.email)) {
                    errors.push('Please enter a valid email address.');
                }
                if (!profile.company) errors.push('Company is required.');
                if (!profile.role) errors.push('Role is required.');
                if (!profile.location) errors.push('Location is required.');
