                lastNameInput.value = DEFAULT_PROFILE.lastName;
                emailInput.value = DEFAULT_PROFILE.email;
                companyInput.value = DEFAULT_PROFILE.company;
                roleInput.value = DEFAULT_PROFILE.role;
                locationInput.value = DEFAULT_PROFILE.location;
                planSelect.value = DEFAULT_PROFILE.plan;
                templateTextarea.value = DEFAULT_TEMPLATE;

                // Initial render
                updateOutputs();
            }

            init();
